const payment=(type,r)=>form(type==='customer'?'Receive customer payment':'Pay supplier',[{name:'amount',label:'Amount',type:'number',required:true,min:'.01',max:Math.max(0,r.outstanding),step:'.01',defaultValue:Math.max(0,r.outstanding)},{name:'mode',label:'Payment method',options:['cash','upi','card','bank'].map(v=>({value:v,label:v.toUpperCase()})),required:true,defaultValue:'cash'},{name:'notes',label:'Reference / notes'},{name:'partyType',label:'',type:'hidden',defaultValue:type},{name:'partyId',label:'',type:'hidden',defaultValue:r.party.id}],'/ops/payments');
