const headerActions={products:can('products.add')&&<Button icon={Plus} kind="primary" onClick={()=>addProduct()}>Add product</Button>,sales:can('sales.add')&&<Button icon={Plus} kind="primary" onClick={()=>go('pos')}>New sale</Button>,customers:can('customers.manage')&&<Button icon={Plus} kind="primary" onClick={()=>form('Add customer',partyFields('customer'),'/customers')}>Add customer</Button>,suppliers:can('suppliers.manage')&&<Button icon={Plus} kind="primary" onClick={()=>form('Add supplier',partyFields('supplier'),'/suppliers')}>Add supplier</Button>,expenses:<Button kind="primary" icon={Plus} onClick={()=>form('Record an expense',[{name:'expenseDate',label:'Date',type:'date',defaultValue:today(),required:true},{name:'category',label:'Category',options:['Rent','Utilities','Wages','Transport','Repairs','Other'].map(v=>({value:v,label:v})),required:true},{name:'description',label:'Description',required:true},{name:'amount',label:'Amount',type:'number',min:'.01',step:'.01',required:true},{name:'paymentMode',label:'Paid via',options:['cash','upi','bank','card'].map(v=>({value:v,label:v.toUpperCase()})),defaultValue:'cash'},{name:'vendor',label:'Paid to'}],'/ops/expenses')}>Add expense</Button>};
